select s.categoria, s.subcategoria, s.ia, s.nombre
from premium_source s
where not exists (
  select 1
  from public.prompts p
  where lower(btrim(p.categoria)) = lower(btrim(s.categoria))
   and lower(btrim(p.subcategoria)) = lower(btrim(s.subcategoria))
   and lower(btrim(p.ia)) = lower(btrim(s.ia))
   and lower(btrim(p.nombre)) = lower(btrim(s.nombre))
)
order by s.categoria, s.subcategoria, s.ia, s.nombre;
